/**
 * Grounding-fixture scene — TEST-SCENE-ONLY, code-split.
 *
 * Loaded via dynamic import() exclusively when `?test-grounding=1` is in the
 * URL (main.ts), so it costs the main bundle nothing: real users never
 * fetch this chunk, mirroring how QuickJS/Havok/decoders stay off the boot
 * path. The e2e grounding specs are its only consumers.
 *
 * Fixtures:
 * - Delayed floor: the player spawns mid-air over NO walkable ground; the
 *   real floor is created (and only then designated walkable) after
 *   FIXTURE_FLOOR_DELAY_MS — a streaming glb floor stand-in.
 * - Backdrop plane below the player: visible, NON-collidable and NOT
 *   designated walkable — the probe must never accept it.
 * - Tall column: the landing target for the ±8192 wrap relocate.
 */
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { AbstractEngine } from '@babylonjs/core/Engines/abstractEngine';
import { Scene } from '@babylonjs/core/scene';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Color3, Color4 } from '@babylonjs/core/Maths/math.color';
import { FreeCamera } from '@babylonjs/core/Cameras/freeCamera';
import { HemisphericLight } from '@babylonjs/core/Lights/hemisphericLight';
import { DirectionalLight } from '@babylonjs/core/Lights/directionalLight';
import { CreateGround } from '@babylonjs/core/Meshes/Builders/groundBuilder';
import { CreateBox } from '@babylonjs/core/Meshes/Builders/boxBuilder';
import { StandardMaterial } from '../engine/shaderImports';
import type { TestSceneResult } from './testScene';

/** Fixture spawn height: the player starts here over NO walkable ground. */
export const FIXTURE_SPAWN_FEET_Y = 6;
/** Delay before the "streaming" floor mesh is created. */
export const FIXTURE_FLOOR_DELAY_MS = 1500;
/** The delayed floor's surface height. */
export const FIXTURE_FLOOR_TOP_Y = 0;
/** Backdrop plane height — BELOW the held player, ABOVE the delayed floor. */
export const FIXTURE_BACKDROP_Y = 3;
/** Tall-column landing target for the ±8192 wrap spec. */
export const FIXTURE_COLUMN_TOP_Y = 50;
export const FIXTURE_COLUMN_X = 10;
export const FIXTURE_COLUMN_Z = 0;

export function createGroundingFixtureScene(engine: AbstractEngine): TestSceneResult {
  const scene = new Scene(engine);
  scene.clearColor = new Color4(0.05, 0.06, 0.09, 1);
  scene.collisionsEnabled = true;

  const camera = new FreeCamera('camera', new Vector3(0, 1.75, -6), scene);

  const hemi = new HemisphericLight('hemi', new Vector3(0, 1, 0), scene);
  hemi.intensity = 0.6;
  const sun = new DirectionalLight('sun', new Vector3(-0.4, -1, 0.6), scene);
  sun.intensity = 0.9;

  const walkableSet = new Set<AbstractMesh>();

  const makeMat = (name: string, r: number, g: number, b: number): StandardMaterial => {
    const mat = new StandardMaterial(name, scene);
    mat.diffuseColor = new Color3(r, g, b);
    return mat;
  };

  // Backdrop: a big plane BELOW the player and ABOVE where the real floor
  // will appear. Visible, but non-collidable and NOT designated walkable —
  // if either filter leaked, the player would hold over it forever or come
  // to rest at y=3 instead of y=0, and the e2e would catch it (AC 2).
  const backdrop = CreateGround('backdrop', { width: 60, height: 60 }, scene);
  backdrop.position = new Vector3(0, FIXTURE_BACKDROP_Y, 0);
  backdrop.material = makeMat('backdropMat', 0.6, 0.35, 0.6);
  backdrop.checkCollisions = false; // deliberate: fall straight through

  // Tall column: the landing target for the ±8192 wrap relocate (AC 3).
  const column = CreateBox(
    'tallColumn',
    { width: 2, depth: 2, height: FIXTURE_COLUMN_TOP_Y },
    scene,
  );
  column.position = new Vector3(FIXTURE_COLUMN_X, FIXTURE_COLUMN_TOP_Y / 2, FIXTURE_COLUMN_Z);
  column.material = makeMat('columnMat', 0.3, 0.5, 0.7);
  column.checkCollisions = true;
  walkableSet.add(column);

  // Delayed floor: simulates a streaming glb floor. Procedural, zero network
  // requests (the e2e request audit must stay clean).
  const timer = setTimeout(() => {
    if (scene.isDisposed) return; // fired after teardown — do nothing
    const floor = CreateGround('delayedFloor', { width: 24, height: 24 }, scene);
    floor.position = new Vector3(0, FIXTURE_FLOOR_TOP_Y, 0);
    floor.material = makeMat('delayedFloorMat', 0.32, 0.4, 0.3);
    floor.checkCollisions = true;
    walkableSet.add(floor);
  }, FIXTURE_FLOOR_DELAY_MS);

  return {
    scene,
    camera,
    spawnFeet: new Vector3(0, FIXTURE_SPAWN_FEET_Y, 0),
    walkables: () => [...walkableSet],
    dispose: () => clearTimeout(timer),
  };
}
